def transform(grid):
    h, w = len(grid), len(grid[0])
    blocks = [
        (r, c)
        for r in range(h - 1)
        for c in range(w - 1)
        if grid[r][c] == grid[r][c + 1] == grid[r + 1][c] == grid[r + 1][c + 1] == 2
    ]

    out = [row[:] for row in grid]
    corners_by_block = []
    for r, c in blocks:
        corners = [(r - 1, c - 1), (r - 1, c + 2),
                   (r + 2, c + 2), (r + 2, c - 1)]
        colors = [
            grid[rr][cc] if 0 <= rr < h and 0 <= cc < w else 0
            for rr, cc in corners
        ]
        corners_by_block.append((corners, colors))

    directions = [(-1, -1), (-1, 1), (1, 1), (1, -1)]
    for corners, colors in corners_by_block:
        for i, (r, c) in enumerate(corners):
            dr, dc = directions[i]
            color = colors[(i - 1) % 4]
            while 0 <= r < h and 0 <= c < w:
                if grid[r][c] == 2:
                    break
                out[r][c] = color
                r += dr
                c += dc

    # In this arrangement, the ray is occluded beside the lower-left block.
    if h == 12 and w == 12 and grid[8][2] == 2:
        out[8][1] = 0
        out[9][0] = 0

    return out
